mapper.select:
select id, api_code, brand_id as brandId, brand_name as brandName, series_id as seriesId, series_name as seriesName, satisfy_province_name as satisfyProvinceName, satisfy_city_name as satisfyCityName, exclude_province_name as excludeProvinceName, exclude_city_name as excludeCityName, province_type as provinceType, demand_id as demandId, daily_limited as dailyLimited, create_time as createTime from b_car_clue_relational_mapping
is_del = 1
and applet_date = #{maxDate}
and api_code = #{cluePushChannel}
and ( brand_name like concat('%', #{search},'%') or series_name like concat('%', #{search},'%') or satisfy_province_name like concat('%', #{search},'%') or satisfy_city_name like concat('%', #{search},'%') or exclude_province_name like concat('%', #{search},'%') or exclude_city_name like concat('%', #{search},'%') )
order by id desc
